def _get_mod():
    global _mod
    if _mod is None:
        os.environ.setdefault('TORCH_CUDA_ARCH_LIST', '9.0a')
        _mod = load_inline(
            name='row_softmax_h100_ext',
            cpp_sources='',
            cuda_sources=_src,
            functions=None,
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _mod

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if (not x.is_cuda) or x.dim() != 2:
            return torch.softmax(x, dim=1)
        if not x.is_contiguous():
            x = x.contiguous()
        y = torch.empty_like(x)
        if x.numel() == 0:
            return y
        _get_mod().row_softmax(x, y)
        return y

